package com.flashlaunch.data

import android.content.Context

/**
 * Toneless pinyin lookup table loaded from `assets/pinyin.dat`.
 *
 * The asset is generated by `tools/gen_pinyin.py` from the public domain
 * mozillazg/pinyin-data set: a syllable string table plus a dense
 * `char - base -> syllable` index for U+3400..U+9FFF.
 */
class PinyinDict private constructor(bytes: ByteArray) {

    private val syllables: Array<String>
    private val base: Int
    private val count: Int
    private val index: ShortArray

    init {
        var p = 4 // magic "PYNT"
        val n = u16(bytes, p); p += 2
        val list = ArrayList<String>(n)
        for (i in 0 until n) {
            val len = bytes[p].toInt() and 0xFF; p += 1
            list.add(String(bytes, p, len, Charsets.US_ASCII)); p += len
        }
        syllables = list.toTypedArray()
        base = u32(bytes, p); p += 4
        count = u32(bytes, p); p += 4
        index = ShortArray(count)
        for (i in 0 until count) {
            index[i] = u16(bytes, p).toShort(); p += 2
        }
    }

    /** Toneless pinyin for one character, or null when unknown. */
    fun pinyinOf(ch: Char): String? {
        val cp = ch.code
        if (cp == 0x3007) return "ling" // 〇 sits outside the dense range
        val off = cp - base
        if (off < 0 || off >= count) return null
        val i = index[off].toInt() and 0xFFFF
        return if (i == 0xFFFF || i >= syllables.size) null else syllables[i]
    }

    /**
     * Splits a label into a searchable full-pinyin string and its initials.
     *
     * 微信      -> ("weixin", "wx")
     * Google Maps -> ("googlemaps", "gm")
     * 36氪      -> ("36ke", "3k")
     */
    fun translate(label: String): Translations {
        val full = StringBuilder(label.length * 3)
        val initials = StringBuilder(label.length)
        var tokenStart = true
        for (raw in label) {
            val ch = raw.lowercaseChar()
            val py = pinyinOf(ch)
            if (py != null) {
                full.append(py)
                if (tokenStart) initials.append(py[0])
                // every han character is its own token
                tokenStart = true
                continue
            }
            if (ch.isLetterOrDigit()) {
                full.append(ch)
                if (tokenStart) {
                    initials.append(ch)
                    tokenStart = false
                }
            } else {
                tokenStart = true
            }
        }
        return Translations(full.toString(), initials.toString())
    }

    data class Translations(val full: String, val initials: String)

    companion object {
        @Volatile
        private var instance: PinyinDict? = null

        fun get(context: Context): PinyinDict = instance ?: synchronized(this) {
            instance ?: PinyinDict(
                context.applicationContext.assets.open("pinyin.dat").use { it.readBytes() }
            ).also { instance = it }
        }

        private fun u16(b: ByteArray, o: Int): Int =
            (b[o].toInt() and 0xFF) or ((b[o + 1].toInt() and 0xFF) shl 8)

        private fun u32(b: ByteArray, o: Int): Int =
            u16(b, o) or (u16(b, o + 2) shl 16)
    }
}
